/* ============================================================
 * SECTION 6 — AUDIT EVENT (core record)
 * ============================================================ */

#define OZAYN_AUDIT_MAX_SOURCE_LEN     64
#define OZAYN_AUDIT_MAX_ACTION_LEN     64
#define OZAYN_AUDIT_MAX_DETAIL_LEN     256
#define OZAYN_AUDIT_MAX_FAILURE_LEN    256
#define OZAYN_AUDIT_MAX_REQUEST_ID_LEN 64
#define OZAYN_AUDIT_MAX_CORR_ID_LEN    64
#define OZAYN_AUDIT_MAX_ID_LEN         64
#define OZAYN_AUDIT_MAX_RESOURCE_ID_LEN 64
#define OZAYN_AUDIT_MAX_METADATA_SIZE  512
#define OZAYN_AUDIT_MAX_EVENT_SIZE     2048

typedef struct {
    /* Core identification */
    char                        event_id[OZAYN_AUDIT_MAX_ID_LEN];
    ozayn_audit_event_type_t    event_type;
    uint32_t                    event_version;
    time_t                      timestamp;

    /* Outcome and severity */
    ozayn_audit_outcome_t       outcome;
    ozayn_audit_severity_t      severity;
    ozayn_audit_category_t      category;

    /* Security context — who and what */
    char                        identity_id[OZAYN_AUDIT_MAX_ID_LEN];
    char                        session_id[OZAYN_AUDIT_MAX_ID_LEN];
    ozayn_authn_method_t        auth_method;
    ozayn_mfa_assurance_t       assurance_level;

    /* Resource reference */
    ozayn_authz_resource_type_t resource_type;
    char                        resource_id[OZAYN_AUDIT_MAX_RESOURCE_ID_LEN];
    ozayn_authz_action_type_t   action;
    ozayn_authz_scope_t         scope;

    /* Source and correlation */
    char                        source_component[OZAYN_AUDIT_MAX_SOURCE_LEN];
    char                        request_id[OZAYN_AUDIT_MAX_REQUEST_ID_LEN];
    char                        correlation_id[OZAYN_AUDIT_MAX_CORR_ID_LEN];

    /* Detail */
    char                        detail[OZAYN_AUDIT_MAX_DETAIL_LEN];
    char                        failure_reason[OZAYN_AUDIT_MAX_FAILURE_LEN];

    /* Metadata — explicitly sanitized, bounded */
    uint8_t                     metadata[OZAYN_AUDIT_MAX_METADATA_SIZE];
    uint32_t                    metadata_size;
    int                         metadata_valid;
} ozayn_audit_event_t;

/* ============================================================
 * SECTION 7 — STORAGE ABSTRACTION
 * ============================================================ */

typedef struct {
    ozayn_audit_result_t (*append)(void *impl, const ozayn_audit_event_t *event);
    ozayn_audit_result_t (*get)(void *impl, const char *event_id, ozayn_audit_event_t *out);
    ozayn_audit_result_t (*count)(void *impl, int *out_count);
    void                 (*shutdown)(void *impl);
} ozayn_audit_storage_ops_t;

typedef struct {
    const char                  *name;
    const ozayn_audit_storage_ops_t *ops;
    void                        *impl;
    int                          initialized;
} ozayn_audit_storage_t;

