#define OZAYN_AUDIT_QUERY_MAX_RESULTS 256

typedef struct {
    ozayn_audit_event_type_t  filter_type;
    int                       filter_type_active;

    char                      filter_identity_id[OZAYN_AUDIT_MAX_ID_LEN];
    int                       filter_identity_active;

    char                      filter_session_id[OZAYN_AUDIT_MAX_ID_LEN];
    int                       filter_session_active;

    ozayn_audit_outcome_t     filter_outcome;
    int                       filter_outcome_active;

    ozayn_audit_severity_t    filter_severity_min;
    int                       filter_severity_active;

    char                      filter_correlation_id[OZAYN_AUDIT_MAX_CORR_ID_LEN];
    int                       filter_correlation_active;

    char                      filter_source[OZAYN_AUDIT_MAX_SOURCE_LEN];
    int                       filter_source_active;

    time_t                    filter_time_from;
    time_t                    filter_time_to;
    int                       filter_time_active;

    int                       result_limit;
    int                       result_offset;
} ozayn_audit_query_t;

